select n.nspname as schema,c.relname as name,c.relkind as kind,pg_get_userbyid(c.relowner) as owner,has_table_privilege(current_user,c.oid,'SELECT') as can_select from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind in ('r','p','m') and n.nspname !~ '^pg_' and n.nspname not in ('information_schema','public','auth','storage','private','identity_private','knowledge_review_private','turn_private','supabase_migrations','community_private','ops_budget_private','place_quota_private','privacy_private','research_intake_private','service_cases_private') order by n.nspname,c.relname;

select jsonb_build_object('counts',jsonb_build_object('realtime.messages',(select count(*) from realtime.messages),'realtime.schema_migrations',(select count(*) from realtime.schema_migrations),'realtime.subscription',(select count(*) from realtime.subscription),'vault.secrets',(select count(*) from vault.secrets)),'catalog',(select jsonb_agg(jsonb_build_object('relation',n.nspname||'.'||c.relname,'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod)) order by a.attnum) from pg_attribute a where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),'extension',(select e.extname from pg_depend d join pg_extension e on e.oid=d.refobjid where d.classid='pg_class'::regclass and d.objid=c.oid and d.deptype='e'),'extensionConfig',(select bool_or(c.oid=any(e.extconfig)) from pg_extension e)) order by n.nspname,c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where (n.nspname,c.relname) in (('realtime','messages'),('realtime','schema_migrations'),('realtime','subscription'),('vault','secrets')))) as metadata;
